// NOVEL (hand-authored) — not generated by CLI Printing Press.
//
// The contract these tests hold: the name `sync` reaches the stub, the stub
// says one thing once, it exits 2, and the generated walker still compiles
// while being unreachable from the command tree.

package cli

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

// syncCommandInTree returns the command registered under `sync`.
func syncCommandInTree(t *testing.T) *cobra.Command {
	t.Helper()
	for _, child := range RootCmd().Commands() {
		if child.Name() == "sync" {
			return child
		}
	}
	t.Fatal("no command is registered under `sync`; the generated hints that say \"run garmin-pp-cli sync first\" would hit an unknown command")
	return nil
}

// The name `sync` must resolve to the stub, not to newSyncCmd. The marker is
// --resources, which the generated walker declares (internal/cli/sync.go:364)
// and the stub deliberately does not: the stub has no flags of its own.
func TestSyncCommand_RegisteredUnderSyncIsTheStub(t *testing.T) {
	registered := syncCommandInTree(t)
	if registered.Flags().Lookup("resources") != nil {
		t.Fatal("the command registered under `sync` declares --resources, so it is the generated walker rather than the stub")
	}

	// The same marker on a freshly built generated command, which proves the
	// assertion above is a real discriminator and not a flag that no longer
	// exists — and keeps newSyncCmd compiled, which is the point of leaving
	// generated sync.go untouched.
	generated := newSyncCmd(&rootFlags{})
	if generated.Name() != "sync" {
		t.Fatalf("newSyncCmd is named %q; the stub shadows it by name", generated.Name())
	}
	if generated.Flags().Lookup("resources") == nil {
		t.Fatal("newSyncCmd no longer declares --resources, so the marker above proves nothing")
	}
}

// The generated walker must not be reachable under any other name either: a
// second registration would give the archive two writers again.
func TestSyncCommand_GeneratedWalkerIsUnreachableFromTheTree(t *testing.T) {
	queue := []*cobra.Command{RootCmd()}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		for _, child := range current.Commands() {
			if child.Flags().Lookup("resources") != nil && child.Flags().Lookup("latest-only") != nil {
				t.Fatalf("command %q carries the generated sync's flags; the generated walker is reachable", child.CommandPath())
			}
			queue = append(queue, child)
		}
	}
}

func TestSyncStub_PrintsOneLineToStderrAndExitsTwo(t *testing.T) {
	cmd := newGarminSyncStubCmd(&rootFlags{})
	var out, errBuf bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errBuf)
	cmd.SetArgs(nil)

	err := cmd.Execute()
	if err == nil {
		t.Fatal("`sync` must exit non-zero; a zero exit reads as a successful sync that stored nothing")
	}
	if got := ExitCode(err); got != 2 {
		t.Fatalf("ExitCode = %d, want 2", got)
	}
	if got := errBuf.String(); got != garminSyncSupersededMessage+"\n" {
		t.Fatalf("stderr = %q, want exactly %q once", got, garminSyncSupersededMessage+"\n")
	}
	if out.Len() != 0 {
		t.Fatalf("stdout = %q, want nothing: the pointer belongs on stderr", out.String())
	}
}

func TestSyncStub_JSONEmitsExactlyOneEventLine(t *testing.T) {
	cmd := newGarminSyncStubCmd(&rootFlags{asJSON: true})
	var out, errBuf bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errBuf)
	cmd.SetArgs(nil)

	err := cmd.Execute()
	if err == nil || ExitCode(err) != 2 {
		t.Fatalf("err = %v, exit = %d, want a code-2 error", err, ExitCode(err))
	}
	lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
	if len(lines) != 1 {
		t.Fatalf("stdout carried %d lines, want exactly 1: %q", len(lines), out.String())
	}
	var event map[string]string
	if decodeErr := json.Unmarshal([]byte(lines[0]), &event); decodeErr != nil {
		t.Fatalf("stdout line is not JSON (%v): %s", decodeErr, lines[0])
	}
	if event["event"] != garminSyncSupersededEvent {
		t.Fatalf("event = %q, want %q", event["event"], garminSyncSupersededEvent)
	}
	if !strings.Contains(event["hint"], "history") {
		t.Fatalf("hint = %q; a machine caller has to be told what to run instead", event["hint"])
	}
	if errBuf.Len() != 0 {
		t.Fatalf("stderr = %q, want nothing in --json mode: the event already carries the message", errBuf.String())
	}
}

// Exit 2 is the same number a bad flag returns, but this is not a Cobra usage
// failure and must not be journalled as one.
func TestSyncStub_IsNotClassifiedAsACobraUsageError(t *testing.T) {
	err := garminSyncSupersededErr()
	if ExitCode(err) != 2 {
		t.Fatalf("ExitCode = %d, want 2", ExitCode(err))
	}
	if isCobraUsageError(err) {
		t.Fatal("the superseded error classifies as a Cobra usage error; the journal would record a flag mistake that never happened")
	}
}

// The wording is the contract N131 D11 fixed; a constant compared to itself
// would not notice it changing.
func TestSyncStub_MessageAndEventAreTheWordingD11Fixed(t *testing.T) {
	if garminSyncSupersededMessage != "sync is superseded by history; run `garmin-pp-cli history`" {
		t.Fatalf("message = %q; D11 fixed this wording and the README, SKILL and patch records quote it", garminSyncSupersededMessage)
	}
	if garminSyncSupersededEvent != "sync_superseded" {
		t.Fatalf("event = %q, want sync_superseded", garminSyncSupersededEvent)
	}
}
